import React, { useState, useEffect, useRef } from 'react';
import { Layout, Input, Table, Button, Row, Col } from 'antd';
import {
    SearchOutlined,
    PlusOutlined,
    DownloadOutlined
} from '@ant-design/icons';
import { useTranslation } from 'react-i18next';
import Sidebar from '../../../components/Layout/Sidebar';
import Navbar from '../../../components/Layout/Navbar';
import { saveAs } from 'file-saver';
import Highlighter from 'react-highlight-words';

const { Header } = Layout;

export default function LecturerManagement() {
    const { t } = useTranslation();
    const [collapsed, setCollapsed] = useState(false);
    const [searchValue, setSearchValue] = useState('');
    const [lecturers, setLecturers] = useState([]);
    const [selectedRowKeys, setSelectedRowKeys] = useState([]);
    const [searchText, setSearchText] = useState('');
    const [searchedColumn, setSearchedColumn] = useState('');
    const searchInput = useRef(null);

    useEffect(() => {
        document.title = "FACE CLASS - Lecturer Management";
        setLecturers([
            { key: '1', lecturerId: 'LT001', name: 'Nguyễn Văn A', email: 'a@example.com', phone: '0123456789', department: 'CNTT', class: 'KTPM01' },
            { key: '2', lecturerId: 'LT002', name: 'Trần Thị B', email: 'b@example.com', phone: '0987654321', department: 'Kinh tế', class: 'QTKD02' },
        ]);
    }, [t]);

    const getColumnSearchProps = (dataIndex) => ({
        filterDropdown: ({ setSelectedKeys, selectedKeys, confirm, clearFilters }) => (
            <div style={{ padding: 8 }}>
                <Input
                    ref={searchInput}
                    placeholder={`Tìm kiếm ${dataIndex}`}
                    value={selectedKeys[0]}
                    onChange={e => setSelectedKeys(e.target.value ? [e.target.value] : [])}
                    onPressEnter={() => handleSearch(selectedKeys, confirm, dataIndex)}
                    style={{ width: 188, marginBottom: 8, display: 'block' }}
                />
                <div style={{ display: 'flex', gap: 8 }}>
                    <Button
                        type="primary"
                        onClick={() => handleSearch(selectedKeys, confirm, dataIndex)}
                        icon={<SearchOutlined />}
                        size="small"
                        style={{ width: 90 }}
                    >
                        Tìm
                    </Button>
                    <Button
                        onClick={() => handleReset(clearFilters)}
                        size="small"
                        style={{ width: 90 }}
                    >
                        Reset
                    </Button>
                </div>
            </div>
        ),
        filterIcon: (filtered) => (
            <SearchOutlined style={{ color: filtered ? '#1890ff' : undefined }} />
        ),
        onFilter: (value, record) =>
            record[dataIndex]?.toString().toLowerCase().includes(value.toLowerCase()),
        filterDropdownProps: {
            onOpenChange: (visible) => {
                if (visible) {
                    setTimeout(() => searchInput.current?.select(), 100);
                }
            }
        },
        render: (text) =>
            searchedColumn === dataIndex ? (
                <Highlighter
                    highlightStyle={{ backgroundColor: '#ffc069', padding: 0 }}
                    searchWords={[searchText]}
                    autoEscape
                    textToHighlight={text ? text.toString() : ''}
                />
            ) : (
                text
            ),
    });

    const handleSearch = (selectedKeys, confirm, dataIndex) => {
        confirm();
        setSearchText(selectedKeys[0]);
        setSearchedColumn(dataIndex);
    };

    const handleReset = (clearFilters) => {
        clearFilters();
        setSearchText('');
    };

    const columns = [
        {
            title: 'ID',
            dataIndex: 'lecturerId',
            key: 'lecturerId',
            width: 80,
            ...getColumnSearchProps('lecturerId')
        },
        {
            title: 'Họ tên',
            dataIndex: 'name',
            key: 'name',
            ...getColumnSearchProps('name')
        },
        {
            title: 'Email',
            dataIndex: 'email',
            key: 'email',
            ...getColumnSearchProps('email')
        },
        {
            title: 'Số điện thoại',
            dataIndex: 'phone',
            key: 'phone',
            ...getColumnSearchProps('phone')
        },
        {
            title: 'Khoa',
            dataIndex: 'department',
            key: 'department',
            ...getColumnSearchProps('department')
        },
        {
            title: 'Lớp',
            dataIndex: 'class',
            key: 'class',
            ...getColumnSearchProps('class')
        },
        {
            title: 'Hành động',
            key: 'action',
            render: (_, record) => (
                <div className="flex gap-2">
                    <Button size="small">Chi tiết</Button>
                    <Button danger size="small">Tạm dừng</Button>
                </div>
            )
        }
    ];

    const filteredStudents = lecturers.filter(student =>
        student.name.toLowerCase().includes(searchValue.toLowerCase()) ||
        student.email.toLowerCase().includes(searchValue.toLowerCase())
    );

    const rowSelection = {
        selectedRowKeys,
        onChange: (newSelectedKeys) => {
            setSelectedRowKeys(newSelectedKeys);
        },
    };

    const convertToCSV = (arr) => {
        if (!arr.length) return '';
        const keys = Object.keys(arr[0]);
        const header = keys.join(',');
        const rows = arr.map(obj => keys.map(k => `"${obj[k] ?? ''}"`).join(','));
        return [header, ...rows].join('\n');
    };

    const exportCSV = () => {
        const now = new Date();
        const filename = `danh_sach_sinh_vien_${now.toISOString().replace(/[-:.]/g, '').slice(0, 15)}.csv`;
        const csv = convertToCSV(filteredStudents);
        const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
        saveAs(blob, filename);
    };

    return (
        <Layout style={{ minHeight: '100vh' }}>
            <Sidebar collapsed={collapsed} setCollapsed={setCollapsed} t={t} />
            <Layout>
                <Header className="bg-white px-4 flex flex-col sm:flex-row justify-between items-center gap-4 py-3 border-b">
                    <Navbar
                        searchValue={searchValue}
                        setSearchValue={setSearchValue}
                    />
                </Header>

                <main className="mx-4 my-4 p-4 sm:p-6 bg-white rounded shadow">
                    <div className="flex justify-between items-center mb-6">
                        <h1 className="text-2xl font-bold">{t('Lecturer Management')}</h1>
                    </div>

                    <Row gutter={[16, 16]} className="mb-4">
                        <Col xs={24} sm={12} md={8}>
                            <Button type="primary" size='large' icon={<PlusOutlined />} href='/admin/management/lecturer/create'>{t('Add Lecturer')}</Button>
                        </Col>
                        <Col xs={24} sm={12} md={8}>
                            <Button
                                type="primary"
                                size='large'
                                icon={<DownloadOutlined />}
                                onClick={exportCSV}
                                style={{ marginBottom: 16 }}
                            >
                                Xuất file CSV
                            </Button>
                        </Col>
                    </Row>

                    <Table
                        rowSelection={rowSelection}
                        columns={columns}
                        dataSource={filteredStudents}
                        pagination={{ pageSize: 10 }}
                        scroll={{ x: 1000 }}
                        bordered
                    />
                </main>
            </Layout>
        </Layout>
    );
};