import React, { useState, useEffect } from 'react';
import {
    Table,
    Button,
    Input,
    Space,
    Upload,
    message,
    Layout,
    Typography,
    Row,
    Col
} from 'antd';
import {
    UploadOutlined,
    EditOutlined,
    DeleteOutlined,
    SaveOutlined,
    CloseOutlined,
    CheckCircleOutlined,
    ArrowLeftOutlined
} from '@ant-design/icons';
import Papa from 'papaparse';
import * as XLSX from 'xlsx';
import Sidebar from '../../../components/Layout/Sidebar';
import Navbar from '../../../components/Layout/Navbar';
import { useTranslation } from 'react-i18next';
import { useNavigate } from 'react-router-dom';

const { Header, Content } = Layout;
const { Title } = Typography;

const StudentCreate = () => {
    const [students, setStudents] = useState([]);
    const [editingKey, setEditingKey] = useState('');
    const [selectedRowKeys, setSelectedRowKeys] = useState([]);
    const [collapsed, setCollapsed] = useState(false);
    const [searchValue, setSearchValue] = useState('');
    const navigate = useNavigate();

    const { t } = useTranslation();

    const isEditing = (record) => record.key === editingKey;

    useEffect(() => {
        document.title = "FACE CLASS - Create Student";
    }, [t]);

    const edit = (record) => {
        setEditingKey(record.key);
    };

    const save = (key) => {
        setEditingKey('');
        message.success('Đã lưu thông tin sinh viên.');
    };

    const cancel = () => {
        setEditingKey('');
    };

    const handleDelete = (key) => {
        setStudents(students.filter((item) => item.key !== key));
        message.success('Đã xoá sinh viên.');
    };

    const handleFileUpload = (file) => {
        const ext = file.name.split('.').pop().toLowerCase();
        const reader = new FileReader();

        reader.onload = (e) => {
            let data = [];
            if (ext === 'csv') {
                const parsed = Papa.parse(e.target.result, { header: true });
                data = parsed.data;
            } else {
                const wb = XLSX.read(e.target.result, { type: 'binary' });
                const ws = wb.Sheets[wb.SheetNames[0]];
                data = XLSX.utils.sheet_to_json(ws);
            }

            const mapped = data.map((item, index) => ({
                key: `${index}-${Date.now()}`,
                studentId: item.studentId || '',
                name: item.name || '',
                email: item.email || '',
                phone: item.phone || '',
                department: item.department || '',
                class: item.class || '',
                status: item.status || '',
            }));

            setStudents(mapped);
            message.success('Tải dữ liệu thành công!');
        };

        if (ext === 'csv') reader.readAsText(file);
        else reader.readAsBinaryString(file);

        return false;
    };

    const handleConfirmCreateAccounts = () => {
        if (selectedRowKeys.length === 0) {
            message.warning('Vui lòng chọn ít nhất một sinh viên!');
            return;
        }

        const selectedStudents = students.filter((item) =>
            selectedRowKeys.includes(item.key)
        );

        console.log('Tạo tài khoản cho:', selectedStudents);
        message.success(`Đã gửi yêu cầu tạo tài khoản cho ${selectedStudents.length} sinh viên.`);
    };

    const columns = [
        {
            title: 'Mã sinh viên',
            dataIndex: 'studentId',
            editable: true,
            render: (text, record) => isEditing(record) ? <Input defaultValue={text} /> : text,
        },
        {
            title: 'Họ và tên',
            dataIndex: 'name',
            editable: true,
            render: (text, record) => isEditing(record) ? <Input defaultValue={text} /> : text,
        },
        {
            title: 'Email',
            dataIndex: 'email',
            editable: true,
            render: (text, record) => isEditing(record) ? <Input defaultValue={text} /> : text,
        },
        {
            title: 'Số điện thoại',
            dataIndex: 'phone',
            editable: true,
            render: (text, record) => isEditing(record) ? <Input defaultValue={text} /> : text,
        },
        {
            title: 'Khoa',
            dataIndex: 'department',
            editable: true,
            render: (text, record) => isEditing(record) ? <Input defaultValue={text} /> : text,
        },
        {
            title: 'Lớp',
            dataIndex: 'class',
            editable: true,
            render: (text, record) => isEditing(record) ? <Input defaultValue={text} /> : text,
        },
        {
            title: 'Trạng thái',
            dataIndex: 'status',
            editable: true,
            render: (text, record) => isEditing(record) ? <Input defaultValue={text} /> : text,
        },
        {
            title: 'Hành động',
            render: (_, record) => {
                const editable = isEditing(record);
                return editable ? (
                    <Space>
                        <Button icon={<SaveOutlined />} onClick={() => save(record.key)}>Xác nhận</Button>
                        <Button icon={<CloseOutlined />} onClick={cancel}>Huỷ</Button>
                    </Space>
                ) : (
                    <Space>
                        <Button icon={<EditOutlined />} onClick={() => edit(record)}>Sửa</Button>
                        <Button icon={<DeleteOutlined />} onClick={() => handleDelete(record.key)} danger>Xoá</Button>
                    </Space>
                );
            },
        },
    ];

    return (
        <Layout style={{ minHeight: '100vh' }}>
            <Sidebar collapsed={collapsed} setCollapsed={setCollapsed} />
            <Layout>
                <Header className="bg-white px-4 flex flex-col sm:flex-row justify-between items-center gap-4 py-3 border-b">
                    <Navbar
                        searchValue={searchValue}
                        setSearchValue={setSearchValue}
                    />
                </Header>
                <Content className="p-4 sm:p-6 md:p-8 bg-white overflow-auto">
                    <div className="flex justify-between items-center mb-6">
                        <div className="flex items-center gap-4">
                            <Button icon={<ArrowLeftOutlined />} onClick={() => navigate(-1)}>
                                Quay lại
                            </Button>
                            <Title level={3} className="!mb-0">Tạo tài khoản giảng viên</Title>
                        </div>
                    </div>

                    <Row gutter={[16, 16]} className="mb-4">
                        <Col xs={24} sm={12} md={8}>
                            <Upload
                                beforeUpload={handleFileUpload}
                                showUploadList={false}
                                accept=".csv,.xlsx"
                            >
                                <Button icon={<UploadOutlined />} type="primary" block size='large'>
                                    Tải lên file CSV/XLSX
                                </Button>
                            </Upload>
                        </Col>
                        <Col xs={24} sm={12} md={8}>
                            <Button
                                icon={<CheckCircleOutlined />}
                                type="primary"
                                onClick={handleConfirmCreateAccounts}
                                block
                                size='large'
                            >
                                Xác nhận tạo tài khoản hàng loạt
                            </Button>
                        </Col>
                    </Row>

                    <div className="overflow-auto">
                        <Table
                            rowSelection={{
                                selectedRowKeys,
                                onChange: setSelectedRowKeys,
                            }}
                            columns={columns}
                            dataSource={students}
                            pagination={{ pageSize: 10 }}
                            scroll={{ x: 1000 }}
                            bordered
                        />
                    </div>
                </Content>
            </Layout>
        </Layout>
    );
};

export default StudentCreate;
