import React, { useEffect, useState } from "react";
import Header from "../../components/Header/Header";
import { useTranslation } from 'react-i18next';
import {
  Card,
  Breadcrumb,
  Tabs,
  Calendar,
  Badge
} from "antd";
import {
  HomeOutlined,
  ScheduleOutlined,
  BookOutlined
} from '@ant-design/icons';

const weeklySchedule = {
  Monday: [
    { subject: "Toán", time: "7:00 - 8:30", lectureName: "Nguyễn Văn A", rooName: "A01" },
    { subject: "Lý", time: "9:00 - 10:30", lectureName: "Nguyễn Văn B", rooName: "A03" }
  ],
  Tuesday: [{ subject: "Hóa", time: "7:00 - 8:30" }],
  Wednesday: [],
  Thursday: [{ subject: "Sinh", time: "10:00 - 11:30" }],
  Friday: [{ subject: "Văn", time: "13:00 - 14:30" }],
  Saturday: [],
  Sunday: []
};

const monthlyEvents = [
  { date: "2025-06-09", subject: "Kiểm tra Toán" },
  { date: "2025-06-15", subject: "Thuyết trình Sinh học" }
];

export default function TimeTablePage() {
  const { t } = useTranslation();
  const [activeTab, setActiveTab] = useState("week");

  useEffect(() => {
    document.title = "FACE CLASS - " + t('timetable');
  }, [t]);

  const WeekView = () => {
    const days = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
    const shortDays = ["T2", "T3", "T4", "T5", "T6", "T7", "CN"];

    return (
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-7 gap-4 mt-4">
        {days.map((day, index) => (
          <div key={day} className="border border-gray-200 p-4 rounded-xl transition">
            <h3 className="font-semibold flex items-center mb-2">
              <BookOutlined className="mr-2" /> {shortDays[index]}
            </h3>
            {weeklySchedule[day].length === 0 ? (
              <p className="text-gray-400 italic">Không có tiết học</p>
            ) : (
              weeklySchedule[day].map((item, idx) => (
                <div key={idx} className="mb-3 border-b pb-2">
                  <p className="font-medium">{item.subject}</p>
                  <p className="text-sm text-gray-500">{item.time}</p>
                  <p className="text-sm text-gray-500 italic">GV: {item.lectureName}</p>
                  <p className="text-sm text-gray-500 italic">Phòng: {item.rooName}</p>
                </div>
              ))
            )}
          </div>
        ))}
      </div>
    );
  };

  const MonthView = () => {
    const getListData = (value) => {
      const dateStr = value.format("YYYY-MM-DD");
      return monthlyEvents.filter((event) => event.date === dateStr);
    };

    const dateCellRender = (value) => {
      const listData = getListData(value);
      return (
        <ul className="list-none p-0 m-0">
          {listData.map((item, index) => (
            <li key={index} className="text-sm">
              <Badge status="processing" text={item.subject} />
            </li>
          ))}
        </ul>
      );
    };

    return (
      <div className="mt-4">
        <Calendar dateCellRender={dateCellRender} />
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-white text-gray-800 flex flex-col">
      <div className="w-full mx-auto px-6 flex-grow">
        <Header />

        <main className="m-auto mt-10 px-4">
          <div className="w-full px-2 mb-6">
            <Breadcrumb
              items={[
                { href: '/', title: <HomeOutlined /> },
                { href: '/timetable', title: <><ScheduleOutlined /> <span>{t('timetable')}</span></> },
                { title: t('timetable') },
              ]}
            />
          </div>

          <Card
            title={<h1 className="text-xl font-bold">{t('timetable')}</h1>}
            className="rounded-2xl"
          >
            <Tabs
              activeKey={activeTab}
              onChange={(key) => setActiveTab(key)}
              tabBarGutter={32}
              type="line"
              size="large"
            >
              <Tabs.TabPane tab="Theo tuần" key="week">
                <WeekView />
              </Tabs.TabPane>
              <Tabs.TabPane tab="Theo tháng" key="month">
                <MonthView />
              </Tabs.TabPane>
            </Tabs>
          </Card>
        </main>
      </div>

      <footer className="bg-gray-100 mt-20 py-2 px-5">
        <div className="text-center text-sm text-gray-500 mt-0">
          © {new Date().getFullYear()} EDU FACE ID. All rights reserved.
        </div>
      </footer>
    </div>
  );
}
