import React, { useState, useEffect } from "react";
import { Button, Drawer } from "antd";
import {
  HomeOutlined,
  CheckCircleOutlined,
  TeamOutlined,
  PhoneOutlined,
  SnippetsOutlined,
  ScanOutlined,
  SettingOutlined,
  MenuOutlined,
  UserOutlined,
  LoginOutlined,
  UserAddOutlined,
  BarChartOutlined,
  PlusCircleOutlined,
  WechatWorkOutlined,
  AuditOutlined,
  LogoutOutlined,
  UserSwitchOutlined,
  ScheduleOutlined
} from "@ant-design/icons";

import Logo from "../../assets/general/face-recognition.png";
import DesktopMenu from "./DesktopMenu";
import MobileMenu from "./MobileMenu";
import i18n from 'i18next';
import { useTranslation } from 'react-i18next';

export default function Header() {
  const [openDrawer, setOpenDrawer] = useState(false);
  const { t } = useTranslation();

  const [user, setUser] = useState(null);

  useEffect(() => {
    const storedUser = localStorage.getItem('user');
    if (storedUser && storedUser !== 'undefined') {
      try {
        setUser(JSON.parse(storedUser));
      } catch (err) {
        console.error('Error parsing user from localStorage:', err);
        localStorage.removeItem('user');
        setUser(null);
      }
    } else {
      setUser(null);
    }
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("user");
    setUser(null);
    window.location.href = "/account/login";
  };

  const items = [
    {
      key: "home",
      icon: <HomeOutlined />,
      label: (
        <a href="/" className="text-base">{t('home')}</a>
      ),
    },
    {
      key: "attendance",
      icon: <CheckCircleOutlined />,
      label: (
        <a href="/attendance" className="text-base">{t('attendance')}</a>
      ),
    },
    {
      key: "timetable",
      icon: <ScheduleOutlined />,
      label: (
        <a href="/timetable" className="text-base">{t('timetable')}</a>
      ),
    },
    {
      key: "contact",
      label: (
        <a href="/contact" className="text-base">{t('contact')}</a>
      ),
      icon: <PhoneOutlined />,
    },
    {
      key: "user",
      icon: <UserOutlined />,
      label: <span className="text-base">{t('setting')}</span>,
      children: !user
        ? [
          {

            key: "login-prompt",
            label: (
              <a href="/account/login">
                Đăng nhập để thực hiện các chức năng
              </a>
            ),
            icon: <LoginOutlined />,

          },
        ]
        : [
          {
            key: "admin",
            label: (
              <a href="/admin/dashboard" target="_blank" rel="noopener noreferrer">
                Admin
              </a>
            ),
            icon: <UserSwitchOutlined />,
            
          },
          {
            key: "add-face",
            label: <a href="/add-face">{t('add_face')}</a>,
            icon: <ScanOutlined />,
          },
          {
            key: "event",
            label: <span>{t('create_event')}</span>,
            icon: <PlusCircleOutlined />,
            children: [
              {
                key: "add-reminder",
                label: <a href="/add-event/add-reminder">{t('create_reminder')}</a>,
                icon: <WechatWorkOutlined />,
              },
              {
                key: "request-leave",
                label: <a href="/add-event/request-leave">{t('request_leave')}</a>,
                icon: <AuditOutlined />,
              },
            ],
          },
          {
            key: "user-information-account",
            label: <a href="/account/information-account">{t('account_info')}</a>,
            icon: <SnippetsOutlined />,
          },
          {
            key: "change-password",
            label: <a href="/account/change-password">{t('change_password')}</a>,
            icon: <TeamOutlined />,
          },
          {
            key: "general-setting",
            label: <a href="/general-setting">{t('general_setting')}</a>,
            icon: <SettingOutlined />,
          },
          {
            key: "statistic",
            label: <a href="/attendance-statistics">{t('attendance_stat')}</a>,
            icon: <BarChartOutlined />,
          },
          {
            key: "logout",
            onClick: handleLogout,
            label: <span style={{ color: 'red' }}>{t('logout')}</span>,
            icon: <LogoutOutlined style={{ color: 'red' }} />,
          },
        ],
    }
    ,
    {
      key: "language",
      label: (
        <span className="text-base">
          <i className="fa-solid fa-language"></i>&nbsp;&nbsp;{t('language')}
        </span>
      ),
      children: [
        {
          key: "vi",
          label: (
            <span className="flex items-center">
              <img
                src="https://flagcdn.com/w40/vn.png"
                alt="Vietnam"
                className="w-7 h-5 mr-2"
              />
              {t('vietnamese')}
            </span>
          ),
        },
        {
          key: "en",
          label: (
            <span className="flex items-center">
              <img
                src="https://flagcdn.com/w40/gb.png"
                alt="UK"
                className="w-7 h-5 mr-2"
              />
              {t('english')}
            </span>
          ),
        },
      ],
    }
  ];

  return (
    <header className="flex justify-between items-center py-6 border-b border-gray-200 w-full">
      <div className="flex items-center space-x-4">
        <a href="/" className="flex items-center space-x-3 hover:opacity-90 transition">
          <img src={Logo} alt="Logo" className="h-10 w-10 object-contain" />
          <span className="text-2xl font-bold text-gray-800 tracking-wide">
            FACE <span>CLASS</span>
          </span>
        </a>
      </div>

      <div className="hidden md:flex flex-grow justify-between items-center ml-10">

        <DesktopMenu
          items={items}
          onClick={({ key }) => {
            if (key === "vi" || key === "en") {
              i18n.changeLanguage(key);
            }
          }}
        />

        <div className="space-x-4 flex-shrink-0">
          <>
            {!user ? (
              <Button icon={<LoginOutlined />} type="primary" size="large" href="/account/login">
                {t('login')}
              </Button>
            ) : (
              <div className="flex items-center space-x-3">
                <Button icon={<UserOutlined />} type="dashed" size="large">
                  <span className="text-base italic">{t('welcome')} {user.fullname}</span>
                </Button>
              </div>
            )}
          </>
        </div>
      </div>

      <div className="md:hidden">
        <Button icon={<MenuOutlined />} onClick={() => setOpenDrawer(true)} />
      </div>

      <Drawer
        title="Menu"
        placement="left"
        onClose={() => setOpenDrawer(false)}
        open={openDrawer}
      >
        <MobileMenu items={items} />
        <div className="mt-4 space-y-2">
          {!user ? (
            <>
              <Button block href="/account/signup" icon={<UserAddOutlined />} size="large">
                Đăng ký
              </Button>
              <Button block type="primary" href="/account/login" icon={<LoginOutlined />} size="large">
                Đăng nhập
              </Button>
            </>
          ) : (
            <div className="flex flex-col space-y-2">
              <span>Xin chào, {user.fullname}
              </span>
            </div>
          )}
        </div>
      </Drawer>
    </header>
  );
}
