import React, { useState, useEffect } from "react";
import { Button, message, Typography } from "antd";
import OtpInput from "../../components/Auth/OtpInput";
import Logo from "../../assets/general/face-recognition.png"
import { useNavigate } from 'react-router-dom';

const { Title } = Typography;

const VerifyOtp = () => {

  useEffect(() => {
    document.title = "FACE CLASS - Xác thực OTP";
  }, []);

  const navigate = useNavigate();
  const [otpCode, setOtpCode] = useState("");
  const [loading, setLoading] = useState(false);

  const handleVerify = () => {
    if (otpCode.length !== 6) {
      return message.error("Vui lòng nhập đủ 6 số OTP");
    }

    const tempUserId = localStorage.getItem("pending_signup");
    const email = localStorage.getItem("otp_email");

    if (!email) {
      return message.error("Không tìm thấy thông tin xác thực, vui lòng đăng ký lại");
    }

    if (!tempUserId) {
      return message.error("Không tìm thấy thông tin xác thực, vui lòng đăng ký lại");
    }

    setLoading(true);

    fetch("http://127.0.0.1:8000/api/accounts/verify_otp/", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        email: email,
        otp: otpCode,
      }),
    })
      .then(async (res) => {
        const data = await res.json();
        setLoading(false);

        if (!res.ok) {
          return message.error(data.error || "Xác minh thất bại");
        }

        localStorage.setItem("access_token", data.access_token);
        localStorage.removeItem("account_id", data.account_id);
        localStorage.setItem("user", JSON.stringify(data.user));

        localStorage.removeItem("pending_signup");
        localStorage.removeItem("otp_email");

        message.success("Đăng ký thành công!");
        navigate("/student/information");
      })
      .catch(() => {
        message.error("Lỗi kết nối");
        setLoading(false);
      });
  };

  return (
    <div className="flex justify-center items-center min-h-screen">
      <div className="bg-white p-8 shadow rounded">
        <img src={Logo} alt="Logo" className="mx-auto mb-5 w-[100px]" />
        <Title level={3} className="text-center">Xác minh OTP</Title>
        <div className="text-center mb-6 mt-6">
          <OtpInput length={6} onComplete={setOtpCode} />
        </div>
        <Button
          type="primary"
          className="mt-4"
          block
          onClick={handleVerify}
          loading={loading}
          size="large"
        >
          Xác nhận
        </Button>
      </div>
    </div>
  );
};

export default VerifyOtp;
