import React, { useEffect } from "react";
import { Form, Button, Input, Typography, message, Radio } from "antd";
import loginImage from '../../assets/general/login.png';
import { IdcardOutlined } from '@ant-design/icons';
import { useNavigate, useLocation } from 'react-router-dom';

const { Title } = Typography;

const Login = () => {

  const [messageApi, contextHolder] = message.useMessage();
  const [form] = Form.useForm();

  const navigate = useNavigate();
  const location = useLocation();
  const redirect = new URLSearchParams(location.search).get("redirect") || "/";

  useEffect(() => {
    document.title = "FACE CLASS - Đăng nhập";

  }, []);

  const onFinish = async (values) => {
    try {
      const response = await fetch("http://127.0.0.1:8000/api/accounts/login/", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(values),
      });

      const data = await response.json();

      if (response.ok) {
        localStorage.setItem("access_token", data.access);
        localStorage.setItem("user", JSON.stringify(data.user));

        messageApi.success("Đăng nhập thành công!");
        navigate(redirect);
      } else {
        if (data.errors?.non_field_errors) {
          messageApi.error(data.errors.non_field_errors[0]);
        } else if (data.errors?.phone_number) {
          messageApi.error("Tài khoản không tồn tại");
        } else {
          messageApi.error("Đăng nhập thất bại");
        }
      }
    } catch (error) {
      messageApi.error("Lỗi kết nối máy chủ");
    }
  };

  const options = [
    { label: 'Sinh viên', value: 3 },
    { label: 'Giảng viên', value: 2 },
  ];

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#f0f2f5] px-4">
      <div className="max-w-[900px] w-full rounded-[12px] overflow-hidden shadow-lg bg-white flex flex-col md:flex-row p-5">

        <div className="hidden md:block md:w-1/2 h-auto">
          <img
            src={loginImage}
            alt="Login illustration"
            className="max-w-full max-h-[400px] object-contain rounded-l-[12px]"
          />
        </div>

        <div className="w-full md:w-1/2 p-8">
          <Title level={2} className="text-center mb-8 text-gray-800">Đăng nhập</Title>
          <>
            {contextHolder}
            <Form
              name="login"
              layout="vertical"
              method="POST"
              form={form}
              onFinish={onFinish}
            >
              <Form.Item
                label="Số điện thoại"
                name="phone_number"
                rules={[
                  { required: true, message: 'Vui lòng nhập số điện thoại!' },
                  {
                    pattern: /^(096|097|086|098|039|038|037|036|035|034|033|032|083|084|085|081|088|082|091|094|070|076|077|078|079|089|090|093|092|056|058|099|059|087)\d{7}$/,
                    message: 'Số điện thoại không hợp lệ!'
                  }
                ]}
              >
                <Input
                  size="large"
                  suffix={<IdcardOutlined />}
                  className="w-[100%]"
                  placeholder="Nhập số điện thoại"
                  maxLength={10}
                />
              </Form.Item>

              <Form.Item
                label="Mật khẩu"
                name="password"
                rules={[
                  { required: true, message: 'Vui lòng nhập mật khẩu!' },
                  {
                    pattern: /^(?=.*[A-Za-z])(?=.*\d)[A-Za-z\d]+$/,
                    message: 'Mật khẩu phải chứa cả chữ và số!',
                  },
                ]}
              >
                <Input.Password
                  size="large"
                  placeholder="Nhập mật khẩu"
                />
              </Form.Item>

              <Form.Item
                label="Bạn là"
                name="role"
                rules={[{ required: true, message: 'Vui lòng chọn vai trò của bạn!' }]}
              >
                <Radio.Group
                  id="role"
                  options={options}
                  optionType="button"
                  buttonStyle="solid"
                />
              </Form.Item>

              <div className="text-right mb-4">
                <a href="/account/forgot-password" className="text-blue-600 hover:underline text-sm">
                  Quên mật khẩu?
                </a>
              </div>

              <Form.Item>
                <Button type="primary" htmlType="submit" block size="large">
                  Đăng nhập
                </Button>
              </Form.Item>
            </Form>

          </>

          <div className="text-center mb-4">
            <a href="/account/signup" className="text-blue-600 hover:underline text-sm">
              Bạn đã chưa có tài khoản? Đăng ký
            </a>
          </div>
        </div>

      </div>
    </div>
  );
};

export default Login;
