import React, { useEffect, useState } from "react";
import { Form, Button, Input, Typography, message, Radio } from "antd";
import signupImage from '../../assets/general/computer.png';
import { PhoneOutlined, ProfileOutlined } from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';

const { Title } = Typography;

const Signup = () => {
  const [contextHolder] = message.useMessage();
  const [loading, setLoading] = useState(false);
  const [apiErrors, setApiErrors] = useState({});
  const navigate = useNavigate();

  useEffect(() => {
    document.title = "FACE CLASS - Đăng ký";

    fetch('http://127.0.0.1:8000/api/csrf/cookie/', {
      method: 'GET',
      credentials: 'include'
    })
      .then(res => {
        if (!res.ok) {
          throw new Error('Không thể lấy cookie CSRF');
        }
      })
      .catch(err => {
        console.error(err);
      });
  }, []);

  function getCookie(name) {
    let cookieValue = null;
    if (document.cookie && document.cookie !== '') {
      const cookies = document.cookie.split(';');
      for (let i = 0; i < cookies.length; i++) {
        const cookie = cookies[i].trim();
        if (cookie.substring(0, name.length + 1) === (name + '=')) {
          cookieValue = decodeURIComponent(cookie.substring(name.length + 1));
          break;
        }
      }
    }
    return cookieValue;
  }

  const onFinish = async (values) => {
    setLoading(true);
    setApiErrors({});
  
    try {
      const res = await fetch("http://127.0.0.1:8000/api/accounts/send_otp/", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-CSRFToken": getCookie("csrftoken"),
        },
        body: JSON.stringify(values),
      });
  
      const data = await res.json();
  
      if (!res.ok) {
      
        let messages = [];
      
        if (data.error && typeof data.error === 'object') {
          messages = Object.values(data.error)
            .map(arr => Array.isArray(arr) ? arr.join(', ') : arr)
            .filter(Boolean);
        } else if (data.error && typeof data.error === 'string') {
          messages = [data.error];
        }
      
        if (messages.length === 0) {
          messages = ["Đăng ký không thành công."];
        }
      
        messages.forEach(msg => message.error(msg));
        setLoading(false);
        return;
      }

      localStorage.setItem("pending_signup", JSON.stringify(values));
      localStorage.setItem("user", JSON.stringify(values));
      localStorage.setItem("otp_email", values.email);
      localStorage.setItem("reset_token", getCookie("csrftoken"));
      setLoading(false);
      navigate("/verify-otp");
  
    } catch (err) {
      console.error(err);
      setLoading(false);
      message.error("Lỗi gửi OTP.");
    }
  };
  

  const options = [
    { label: 'Sinh viên', value: 3 },
    { label: 'Giảng viên', value: 2 },
  ];

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#f0f2f5] px-4">
      <div className="max-w-[900px] w-full rounded-[12px] overflow-hidden shadow-lg bg-white flex flex-col md:flex-row p-5">

        <div className="hidden md:flex md:w-1/2 h-auto items-center justify-center">
          <img
            src={signupImage}
            alt="Login illustration"
            className="max-w-full max-h-[400px] object-contain rounded-l-[12px]"
          />
        </div>

        <div className="w-full md:w-1/2 p-8">
          <>
            {contextHolder}

            <Title level={2} className="text-center mb-8 text-gray-800">Đăng ký</Title>

            <Form
              name="signup"
              onFinish={onFinish}
              layout="vertical"
              method="POST"
            >

              <Form.Item
                label="Số điện thoại"
                name="phone_number"
                validateStatus={apiErrors.phone_number ? 'error' : ''}
                help={apiErrors.phone_number?.[0]}
                rules={[
                  { required: true, message: 'Vui lòng nhập số điện thoại!' },
                  {
                    pattern: /^(096|097|086|098|039|038|037|036|035|034|033|032|083|084|085|081|088|082|091|094|070|076|077|078|079|089|090|093|092|056|058|099|059|087)\d{7}$/,
                    message: 'Số điện thoại không hợp lệ!'
                  }
                ]}
              >
                <Input
                  size="large"
                  suffix={<PhoneOutlined />}
                  placeholder="Nhập số điện thoại"
                  maxLength={10}
                />
              </Form.Item>

              <Form.Item
                label="Email"
                name="email"
                validateStatus={apiErrors.email ? 'error' : ''}
                help={apiErrors.email?.[0]}
                rules={[
                  { required: true, message: 'Vui lòng nhập email!' },
                  { type: 'email', message: 'Email không đúng định dạng!' },
                ]}
              >
                <Input
                  size="large"
                  suffix={<ProfileOutlined />}
                  placeholder="Nhập email"
                />
              </Form.Item>

              <Form.Item
                label="Mật khẩu"
                name="password"
                rules={[
                  { required: true, message: 'Vui lòng nhập mật khẩu!' },
                  {
                    pattern: /^(?=.*[A-Za-z])(?=.*\d)[A-Za-z\d]+$/,
                    message: 'Mật khẩu phải chứa cả chữ và số!',
                  },
                ]}
              >
                <Input.Password
                  size="large"
                  placeholder="Nhập mật khẩu"
                  minLength={6}
                />
              </Form.Item>

              <Form.Item
                label="Bạn là"
                name="role"
                rules={[{ required: true, message: 'Vui lòng chọn vai trò của bạn!' }]}
              >
                <Radio.Group
                  id="role"
                  options={options}
                  optionType="button"
                  buttonStyle="solid"
                />
              </Form.Item>

              <Form.Item>
                <Button type="primary" htmlType="submit" block size="large" loading={loading}>
                  Đăng ký
                </Button>
              </Form.Item>

              <div className="text-center mb-4">
                <a href="/account/login" className="text-blue-600 hover:underline text-sm">
                  Bạn đã có tài khoản? Đăng nhập
                </a>
              </div>
            </Form>
          </>
        </div>
      </div>
    </div>
  );
};

export default Signup;